list.example:
kcds.core.Events.on('consoleCommand', (command) => {
  if (command !== 'queue') {
    return;
  }
  for (const entry of kcds.core.Queue.list()) {
    console.info(`${entry.nickname} waits ${entry.waitedSeconds} s (priority ${entry.priority})`);
  }
});

list.exampleCs:
Events.On("consoleCommand", (string command) =>
{
    if (command != "queue")
    {
        return;
    }
    foreach (var entry in Queue.List())
    {
        Log.Info($"{entry["nickname"]} waits {entry["waitedSeconds"]} s (priority {entry["priority"]})");
    }
});

